#include <iostream>
#include <iomanip>
#include <memory>
#include <vector>
#include <string>

class Employee {
public:
    Employee(std::string name, std::string ssn)
        : name_(std::move(name)), ssn_(std::move(ssn)) {}
    virtual ~Employee() = default;

    virtual double earnings() const = 0;
    virtual void print() const {
        std::cout << name_ << "\nssn: " << ssn_;
    }

private:
    std::string name_;
    std::string ssn_;
};

class SalariedEmployee : public Employee {
public:
    SalariedEmployee(std::string name, std::string ssn, double salary)
        : Employee(std::move(name), std::move(ssn)), weeklySalary_(salary) {}

    double earnings() const override { return weeklySalary_; }
    void print() const override {
        std::cout << "salaried employee: ";
        Employee::print();
        std::cout << "\nweekly salary: " << weeklySalary_;
    }

private:
    double weeklySalary_;
};

class CommissionEmployee : public Employee {
public:
    CommissionEmployee(std::string name, std::string ssn, double sales, double rate)
        : Employee(std::move(name), std::move(ssn)), grossSales_(sales), commissionRate_(rate) {}

    double earnings() const override { return grossSales_ * commissionRate_; }
    void print() const override {
        std::cout << "commission employee: ";
        Employee::print();
        std::cout << "\ngross sales: " << grossSales_
                  << "; commission rate: " << commissionRate_;
    }

private:
    double grossSales_;
    double commissionRate_;
};

void virtualViaPointer(const Employee* baseClassPtr) {
    baseClassPtr->print();
    std::cout << "\nearned $" << baseClassPtr->earnings() << "\n\n";
}

void virtualViaReference(const Employee& baseClassRef) {
    baseClassRef.print();
    std::cout << "\nearned $" << baseClassRef.earnings() << "\n\n";
}

int main() {
    std::cout << std::fixed << std::setprecision(2);

    std::vector<std::unique_ptr<Employee>> employees;
    employees.push_back(std::make_unique<SalariedEmployee>("John Smith", "111-11-1111", 800.00));
    employees.push_back(std::make_unique<CommissionEmployee>("Sue Jones", "333-33-3333", 10000.00, 0.06));

    std::cout << "Via base-class pointer:\n";
    for (const auto& emp : employees) {
        virtualViaPointer(emp.get());
    }

    std::cout << "Via base-class reference:\n";
    for (const auto& emp : employees) {
        virtualViaReference(*emp);
    }

    return 0;
}

#include <iostream>
#include <string_view>

class PlainData {
    int id_{0};
};

class PolymorphicData {
    int id_{0};
public:
    virtual ~PolymorphicData() = default;
    virtual std::string_view describe() const {
        return "PolymorphicData";
    }
};

class DerivedData : public PolymorphicData {
public:
    std::string_view describe() const override {
        return "DerivedData";
    }
};

int main() {
    std::cout << "Size of PlainData: " << sizeof(PlainData) << " bytes\n";
    std::cout << "Size of PolymorphicData: " << sizeof(PolymorphicData) << " bytes\n";
    std::cout << "Size of DerivedData: " << sizeof(DerivedData) << " bytes\n";

    DerivedData derivedObj;
    PolymorphicData* polyPtr = &derivedObj;

    // Polymorphic resolution via vtable lookup
    std::cout << "Invoked describe(): " << polyPtr->describe() << "\n";

    return 0;
}
